                // are keys of 'sources' (docs/courses/counterpoint-love-letter.md).
                'love' => [
                    'kicker' => 'Punctus contra punctum, point against point',
                    'kicker_game' => 'Point vs point',
                    // The eyebrow and the first answer, with the course's count of lessons.
                    'eyebrow' => 'A Plus course · :n lessons',
                    'faq_long' => ':n lessons of 2 to 4 minutes, about 70 minutes in all. Each book ends in a challenge.',
                    'round' => 'Start the round',
                    'again' => 'Hear the round again',
                    'stop' => 'Stop',
                    // Follow one voice of the three: it comes forward, the others step back.
                    'follow' => 'Follow :n',
                    'follow_lead' => 'Follow one voice, before or while it plays: it comes forward and the others step back. Holding one line among three is the course\'s skill.',
                    'follow_label' => 'Follow a voice',
                    'card' => 'Row, Row, Row Your Boat, a round for three',
                    'art_note' => 'Row, Row, Row Your Boat as a round for three, drawn as points joined by threads: the same tune in every voice, each two bars after the last.',
                    // The voices' numbers, beside their threads.
                    'voices' => ['I', 'II', 'III', 'IV'],
                    'streams' => [
                        'kick' => 'The ear',
                        'title' => 'Two tunes, two streams.',
                        'lead' => 'In 1969 a psychologist noticed that a fast run of notes jumping between high and low splits apart: you hear a high tune and a low tune, not one zigzag.',
                        'body' => 'In his lab, listeners easily recognised a pattern inside one stream, but one that crossed between the streams only at chance. Notes close in pitch hang together. That is how the ear holds two melodies at once.',
                        'demo' => 'Split the tune',
                        'demo_lead' => 'The notes take turns, high and low. Speed them up and listen for the moment one zigzag falls apart into two tunes.',
                        'speed' => 'Speed',
                        'slow' => 'Slow',
                        'fast' => 'Fast',
                        'play' => 'Play the run',
                        'one' => 'One zigzag',
                        'two' => 'Two tunes',
                        'one_game' => 'Streams: 1',
                        'two_game' => 'Streams: 2',
                    ],
                    'fusion' => [
                        'kick' => 'Fusion',
                        'title' => 'One voice or two?',
                        'lead' => 'A sung note is a stack of overtones. Two notes an octave apart, a 2 to 1 ratio, line up so well that together they sound like one richer note: researchers call this fusion. The fifth, at 3 to 2, is the next simplest ratio.',
                        'motion' => 'The ear also groups sounds that change together, a principle hearing scientists call common fate. Two voices in parallel fifths fuse and move as one, so they become one hollow voice. In contrary motion one line rises while the other falls, and nothing tells the ear they are one sound.',
                        'bach' => 'An analysis of Bach\'s keyboard counterpoint found he used the most fusing intervals least, keeping his voices apart. A 2001 study derived the old voice-leading rules from such principles of hearing.',
                        'same' => 'Same way',
                        'same_how' => 'The lower line a fifth below, moving with the top.',
                        'opposite' => 'Opposite ways',
                        'opposite_how' => 'The same top line, the lower one moving against it.',
                        'play' => 'Play',
                        'pick' => 'What did you hear?',
                        'one' => 'One voice',
                        'two' => 'Two voices',
                        'same_one' => 'Most ears agree: moving together in fifths, the two lines fuse into one hollow voice.',
                        'same_two' => 'Sharp ears. Most hear one hollow voice here: in parallel fifths, the two lines fuse.',
                        'opposite_two' => 'Most ears agree: one line rises as the other falls, so nothing ties them into one sound.',
                        'opposite_one' => 'Most ears hear two here: one line rises as the other falls, so nothing ties them into one sound.',
                        'melt' => 'Melt the octave',
                        'tabs' => 'Which to hear',
                        'melt_lead' => 'Two voices hold an octave. In tune, they melt into one note. Nudge the top voice out of tune and two notes come back.',
                        'cents' => 'Top voice, in cents',
                        'hold' => 'Hold the octave',
                        'merged' => 'In tune: one note',
                        'apart' => 'Out of tune: two notes',
                        'merged_game' => 'Sync!',
                        'apart_game' => 'Out of sync',
                    ],
                    'books' => [
                        'kick' => 'The books',
                        'title' => 'From a round to your own line.',
                        'free' => 'Free',
                    ],
                    'history' => [
                        'kick' => 'History',
                        'title' => 'A thousand years against the line.',
                        // Game mode's high-score column: how many voices, also the threads drawn above each year.
                        'players' => 'Players: :n',
                        'more' => 'More years',
                        // [when, what happened, its sources, players]
                        'beats' => [
                            ['About 900', 'A teaching book, Musica enchiriadis, describes organum: a second voice copying the chant a fourth or fifth below.', ['norton', 'ucsb'], 2],
                            ['About 1200', 'At Notre-Dame of Paris, Pérotin writes Viderunt omnes, one of only a few four-voice organa known.', ['perotin'], 4],
                            ['1477', 'Johannes Tinctoris says only the music of the last forty years, by the likes of Dufay and Ockeghem, is worth hearing.', ['ucsb', 'bukofzer'], 3],
                            ['The 1500s', 'Palestrina\'s music becomes the model of strict counterpoint; the tale that his Pope Marcellus Mass saved church polyphony is a myth.', ['palestrina'], 4],
                            ['About 1570', 'Thomas Tallis\'s Spem in alium gives forty singers a line each, in eight choirs of five.', ['spem', 'bbcspem'], 40],
                            ['1609', 'Thomas Ravenscroft prints the first Three Blind Mice, a round in a minor key, and "Hold thy peace", the catch from Twelfth Night.', ['pammelia', 'deuteromelia', 'folger'], 3],
                            ['1725', 'Johann Joseph Fux teaches counterpoint in steps, the species, and explains its name: a written note was once a point.', ['ucsb', 'catholic'], 2],
                            ['1761', 'London\'s Noblemen and Gentlemen\'s Catch Club is founded, among the first great clubs to popularise the glee.', ['hamilton'], 3],
                            ['1785', 'Mozart starts his pupil Thomas Attwood on two-part exercises after Fux; the corrected notebook is in the British Library.', ['bl', 'rma', 'interlude'], 2],
                            ['Today', 'In the spirituals a soloist sings and the others answer, a shape passed on into gospel; at carols, a descant soars over the hymn.', ['carnegie', 'descant'], 2],
                        ],
                        // The inline demo, after Tallis's forty: a round for four, building up.
                        'count' => [
                            'title' => 'Count the voices',
                            'lead' => 'A round for four builds up one voice at a time. Press New voice each time you hear one come in.',
                            'play' => 'Play the round',
                            'tap' => 'New voice',
                            'result' => 'You caught :n of :total.',
                            'result_game' => 'Voices detected :n/:total',
                            'note' => 'Missed one? In a 1989 study, even expert musicians lost count at four voices. They mostly guessed too few, and inner voices coming in were the hardest to notice.',
                        ],
                    ],
                    'seek' => [
                        'kick' => 'Quaerendo invenietis',
                        'title' => 'Seek and you shall find.',
                        'lead' => 'After playing for Frederick the Great in 1747, Bach published riddle canons marked "Quaerendo invenietis", seek and you shall find: one written line, and the players must work out where the second voice comes in.',
                        'demo_lead' => 'Here is a short line of our own, sung twice. Move where the copy comes in, and listen for the places it fits.',
                        'delay' => 'Beats before the copy comes in',
                        'fits' => 'Fits smoothly',
                        'rubs' => 'Rubs',
