                        'norton' => ['Norton, Early Organum', 'https://nerd.wwnorton.com/ebooks/epub/concisehwm5anth/EPUB/content/1.3.1-chapter03.xhtml'],
                        'perotin' => ['LibreTexts (Santa Ana College), Perotinus', 'https://human.libretexts.org/Bookshelves/Music/Music_Appreciation/Music_Appreciation_I_(Jones)/01%3A_Medieval_and_Renaissance/1.08%3A_Perotinus_(Perotin)'],
                        'bukofzer' => ['Proc. Musical Assoc. (1938)', 'https://www.cambridge.org/core/journals/proceedings-of-the-musical-association/article/john-dunstable-and-the-music-of-his-time/94E223699FA73BF41DC9F67F9B491317'],
                        'palestrina' => ['Illinois Public Media, Celebrating 500 Years of Palestrina', 'https://will.illinois.edu/clefnotes/entry/celebrating-500-years-of-palestrina'],
