                    'steps' => [
                        'Slide down on a soft "oo", rest on your lowest easy note, then come back up.',
                        'Now slide up, getting quieter as you go, rest on your highest light note, then come back down.',
                        'If anything tightens, tickles or hurts, rest. Don\'t sing when you\'re hoarse or ill.',
                    ],
                    'after' => 'Lesson 1 draws your two slides and scores singing the whole slide, never how high or low it went.',
                ],
                'measures' => 'The app hears your slides and held notes, and where your voice jumps on a siren, if it does: two jumps in the same place are kept as your break. The last lessons score crossing it without a jump.',
                'scoring' => ['game' => 'Up to three stars and XP a lesson. Going higher or lower never earns more.', 'serious' => 'The same lesson shows the plain measure, with no stars or rewards.'],
                'who' => [
                    'Singers whose voice cracks or jumps on the way up.',
                    'Anyone who feels stuck low, or wants high notes that are light and easy.',
                    'Choir singers who want one even sound from low to high.',
                ],
                'need' => [
                    'A quiet spot where you can sing softly.',
                    'A few minutes a day: the slides and sirens are short.',
                    'No reading music: you see your voice drawn as a line.',
