                'learn' => ['Reading the stave', 'Solfège: do re mi', 'Steps, skips and leaps', 'Singing a new line at first sight'],
                'measures' => 'The app follows your voice as you read and hears whether each note lands on the one on the stave. In the lessons in time, it hears when each note starts too. It doesn\'t check your syllables.',
                'safety' => ['Sing at a medium volume, in the middle of your voice.', 'Stop if anything tightens or hurts. Don\'t practise when hoarse or ill.'],
                'songs' => [['Ode to Joy', 'Public domain melody (1824)'], ['Amazing Grace', 'Public domain hymn (words 1779, tune 1829)'], ['Michael, Row the Boat Ashore', 'Traditional, public domain']],
