                'eyebrow' => 'A Plus course',
                'hero_title' => 'See it, then sing it.',
                'hero_lead' => 'Sight-singing is looking at a line of music you\'ve never heard and singing it. You start by finding do, the home note, on the stave, then read steps and skips, then rhythm, and at the end your own part while a choir sings around you.',
                'see_lessons' => 'See the lessons',
                'titles' => [
