                'need' => [
                    'Nothing to read yet: lesson 1 starts with five lines and do.',
                    'A quiet spot and a few minutes at a time.',
                    'A comfortable note of your own: do sits where your voice is easy.',
                ],
                'faq' => [
                    ['Do I need to read music already?', 'No. Lesson 1 starts with five lines and do, with the names under the notes. The names fade, then go, as you get surer.'],
                    ['Why do re mi, and not letter names?', 'Do re mi name each note by its place in the key, so do to mi looks and sounds the same in any key. When the key changes, do moves on the stave, and every other note moves with it.'],
                    ['What if I can\'t find the first note?', 'The early lines sit over a drone on do, and you can hear a line before you read it. Find do first, then count the steps from it.'],
                    ['Is it safe for my voice?', 'Yes. The lines are short, sung at a medium volume in the middle of your voice. Stop if anything tightens or hurts.'],
                    ['What does it cost?', 'When it opens, lesson 1 is free, with no account needed. The rest is part of Plus; saving your progress takes a free account.'],
                ],
                'related' => ['ear-training', 'perfect-your-pitch', 'barbershop'],
                'kicks' => ['story' => 'The story', 'aims' => 'Do is home', 'units' => 'The lessons', 'science' => 'The science', 'margin' => 'Margin notes', 'inside' => 'Listening', 'begin' => 'Before you begin', 'questions' => 'Questions', 'close' => 'Your first line'],
                'close' => 'Lesson 1 takes five lines and do: watch a short line light up over a drone on do, then sing it back.',
                'love' => [
                    'eyebrow' => 'A Plus course · :lessons lessons',
                    'chips' => [':units units, :lessons lessons', 'Names under the notes, then faint, then off', 'Ends with your part in a choir'],
                    // The hero's sol-fa ladder: the scale as rungs, do at the foot and the top.
                    'names' => ['do', 're', 'mi', 'fa', 'so', 'la', 'ti'],
                    'ladder' => ['home' => 'Do, home', 'half' => 'A half step: closer rungs'],
                    'ladder_note' => 'Sarah Glover\'s pupils in Norwich sang sol-fa notes pointed out on a chart, her "Norwich sol-fa ladder".',
                    'ladder_alt' => 'The scale as a ladder of eight rungs, do at the foot and at the top; mi to fa and ti to do are half steps, so those rungs sit closer.',
                    // Find do (js/public/sight-singing.js): a drone on do under a short original line, in C or G.
                    'demo' => [
                        'live' => 'Live demo',
                        'lesson' => 'Lesson 1 · Do on the stave',
                        'key_c' => 'Key of C',
                        'key_g' => 'Key of G',
                        'title' => 'Find do',
                        'lead' => 'A drone holds do, the first note of the scale, under a short line. It moves by steps, with one small leap from mi, the third note of the scale, down to do. Play it, then tap the note that is do. Then hide the names and try a new key: do moves on the stave, and the tune sounds the same, only higher.',
                        'play' => 'Play the line',
                        'stop' => 'Stop',
                        'new_key' => 'New key',
                        'names' => 'Names under the notes',
                        'stave' => 'The line on a stave: six notes, each one a button.',
                        'note_n' => 'Note :n',
                        'ready' => 'Start the line to hear it over a drone on do, then tap the note that is do.',
                        'playing' => 'The drone is do. Watch each note light as it\'s sung.',
                        'after' => 'Which note matched the drone? Tap it.',
                        'right_c' => 'Yes, that\'s do, the first note of the scale and home. In C it sits on the short line below the stave.',
                        'right_g' => 'Yes, that\'s do. In G it sits on the second line up, with one sharp at the start.',
                        'wrong' => 'That\'s :name. Listen: do is the note that matches the drone.',
                        'moved_g' => 'Now in G: one sharp at the start, and every note sits higher. Where\'s do now?',
                        'moved_c' => 'Back in C: no sharps or flats. Where\'s do?',
                        'note' => 'No mic here: the demo only plays. In the course, the app listens as you sing each line.',
                    ],
                    // The story, from the research pack (docs/courses/sight-singing-love-letter.md): [when, title, text, notes].
                    'story' => [
                        ['About 1025', 'Lines a third apart', 'Guido of Arezzo set chant on lines a third apart, marked with letters, so a singer could see how far each note moved. In 1028 he brought his book of chants to Pope John XIX, who was delighted to find he could learn its melodies without a teacher.', ['guido', 'advent']],
                        ['The 1720s', 'Singing schools', 'By the early 1700s, reading notes had become rare in New England. Ministers such as Thomas Walter complained, and in the 1720s singing schools sprang up to teach it.', ['colonial']],
                        ['1801', 'Notes with shapes', 'The Easy Instructor gave each syllable its own shape of note head, so singers with little schooling could read. Travelling singing masters taught in churches and schoolhouses in the months with less farm work.', ['georgia', 'arkansas']],
                        ['1857', 'Sol-fa for everyone', 'John Curwen built on Sarah Glover\'s Norwich method to improve church singing. In May 1857 about 500 Glasgow pupils, from 1,300 who had taken twenty lessons, sang some two dozen pieces unaccompanied in the City Hall. The Glasgow Herald\'s reviewer was "wonder-struck".', ['ihme', 'glasgow']],
                        ['1945', 'Kodály\'s Hungary', 'Zoltán Kodály and his colleagues adapted Glover and Curwen\'s sol-fa for Hungary, and his approach has been in school curricula since 1945. In 1950 the first music primary school opened in Kecskemét, his birthplace, with music for every child every day.', ['kodaly', 'unesco']],
                        ['Today', 'The sight-reading room', 'In Texas, school choirs sing their prepared pieces, then read new music in their own system of numbers or syllables, and judges rate both readings.', ['uil']],
                    ],
                    // The science, in plain words: [title, text, notes].
                    'science' => [
                        ['Your eyes run ahead of your voice', 'Reading music, you look at notes you haven\'t sung yet and hold them in mind until their turn. In eye-tracking studies of reading melodies, skilled readers looked farther ahead, then back to the note being performed. The best readers looked less far ahead when the music got dense.', ['goolsby', 'perra']],
                        ['Do is home, in any key', 'Most adults remember a melody by its relative pitch, not its exact notes, and know it in any key; six-month-old babies already do. Movable do names that relation. In a study of 414 Texas high-school choir singers, movable-do schools outscored fixed-do ones, though the schools differed in other ways too.', ['plantinga', 'demorest']],
                        ['The chord helps you guess right', 'In a 2006 study, 22 experienced singers sight-read their part in chorales. Changing the melody, or making the harmony atonal, in no key at all, raised their pitch errors, and weaker readers were hit harder by the odd harmony.', ['fine']],
                        ['Practice pays', 'A review that pooled 92 studies found sight-reading goes with skills that grow with practice, like ear training and improvising, and not with personality. Another found training gives small but real gains, with singing in solfège among the methods that helped.', ['mishra', 'mishra2']],
                    ],
                    // Notes in the margin (the pack's surprising facts, none told in the app): [text, notes].
                    'margin' => [
                        ['Guido\'s staves were in colour: the line for C yellow, the line for F red. By the 1200s, manuscripts show the colours were thought unnecessary.', ['guido', 'ebsco']],
                        ['Professional pianists read about four notes ahead and amateurs about two, yet both look about one second ahead. At a fast tempo the gap shrinks to about 0.7 seconds; at a slow one it grows to about 1.3.', ['furneaux']],
                        ['In The Easy Instructor (1801), fa was a triangle, sol an oval, la a rectangle and mi a diamond. In 1846 Jesse B. Aikin added three more shapes.', ['arkansas']],
                        ['In the Texas contest, the director gets six minutes to study the new piece and teach it, but may not hum or sing any part. Students may chant the rhythm and words, not the tune.', ['uil']],
                    ],
                    // The sources (docs/courses/sight-singing-love-letter.md), numbered in this order.
                    'sources' => [
                        'glover' => ['Norfolk Record Office, "Sarah Anna Glover"', 'https://norfolkrecordofficeblog.org/sarah-anna-glover'],
                        'guido' => ['Encyclopedia.com, "Guido of Arezzo"', 'https://www.encyclopedia.com/religion/encyclopedias-almanacs-transcripts-and-maps/guido-arezzo'],
                        'advent' => ['Catholic Encyclopedia, "Guido of Arezzo"', 'https://www.newadvent.org/cathen/07065a.htm'],
                        'colonial' => ['Colonial Society of Massachusetts, early New England singing', 'https://www.colonialsociety.org/node/2035'],
                        'georgia' => ['New Georgia Encyclopedia, "Sacred Harp"', 'https://www.georgiaencyclopedia.org/articles/arts-culture/sacred-harp/'],
                        'arkansas' => ['Encyclopedia of Arkansas, "Shape Note Singing"', 'https://encyclopediaofarkansas.net/entries/shape-note-singing-6428/'],
                        'ihme' => ['International History of Music Education, United Kingdom', 'https://ihme.isme.org/ihme1/united_kingdom_gallery.htm'],
                        'glasgow' => ['Glasgow\'s Cultural History, May 1857', 'https://www.glasgowsculturalhistory.com/?p=1300'],
                        'kodaly' => ['International Kodály Society, "Kodály education"', 'https://iks.hu/kodaly_education/'],
                        'unesco' => ['UNESCO, the Kodály concept', 'https://ich.unesco.org/en/BSP/safeguarding-of-the-folk-music-heritage-by-the-kodaly-concept-01177'],
                        'uil' => ['UIL Music Constitution, "Sight-Reading"', 'https://www.uiltexas.org/policy/constitution/music/sight-reading'],
                        'goolsby' => ['Music Perception (1994), eye movements in reading melodies', 'https://doi.org/10.2307/40285756'],
                        'perra' => ['Journal of Eye Movement Research (2021), the eye-hand span in music reading', 'https://doi.org/10.16910/jemr.14.4.4'],
