                        'about' => ['Barbershop Harmony Society, About our music', 'https://barbershop.org/music/about-our-music'],
                        'language' => ['Barbershop Harmony Society, Learning the language', 'https://www.barbershop.org/intro-to-barbershop-learning-the-language-of-barbershop'],
