                'learn' => ['Blue notes', 'Short riffs', 'Runs, slow then up to speed'],
                // The designed page (site/courses/gospel-runs): its own sections and words.
                'app' => 'gospel-runs',
                'hero_title' => 'Clean runs, note by note.',
                'hero_lead' => 'A run is a few notes sung on one syllable, placed where a phrase breathes and sung lightly. The spirituals and gospel, Black American sacred music, are full of them. Learn them the way every fast run is learned: slow, clean and well placed first.',
                'hero_facts' => ['Five minutes or less a lesson', 'Lines of public-domain spirituals', 'No reading music'],
                'see_lessons' => 'See the lessons',
                'see_aims' => 'What you\'ll learn',
                'titles' => [
                    'outcomes' => 'By the end, you can',
