                'outcomes' => [
                    'Sing a run down the five stairs of the major pentatonic, every note clean.',
                    'Hear a clean run from a smeared one, or a choppy one.',
                    'Place one run a line, on a held word, in threes and in fours.',
                    'Bend from the blue third up to the third and land it, then sing a run of your own on Swing Low.',
