                'units_say' => [
                    'The major pentatonic\'s five stairs, a turn, and a run at the end of a line of Swing Low.',
                    'Runs in threes and fours, clean or smeared, where a run goes, and a minor run on Wade in the Water.',
                    'A bend from the blue third up to the third, short runs up into a held note, and a bluesy ending.',
                    'A ladder from 2 to 4 notes a second, Swing Low and Steal Away with a run, and a run of your own.',
                ],
                'try' => [
                    'lead' => 'The first lesson is a taste: five notes down the stairs, on one held word.',
                    'steps' => [
                        'Hear an "Amen" with the run inside it, the chord moving home.',
                        'Hum the run slowly: la, so, mi, re, do.',
                        'Sing it on "A-", two notes a second, and land on do as the chord comes home.',
                    ],
                    'after' => 'Lesson 1 scores each note on landing clean: a note that slid in earns half.',
                ],
                'measures' => 'The app hears each note of your run: whether it landed on its pitch or slid in, and in later lessons whether it started on the beat. A bend is scored on where it arrives, not on its loose start. Faster than 4 notes a second it doesn\'t score yet: that\'s a check you make yourself.',
                'scoring' => ['game' => 'Up to three stars and XP a lesson, for the notes you land.', 'serious' => 'The same lesson shows the plain measure, with no stars or rewards.'],
                'who' => [
                    'Singers who want runs that stay clean, separate notes.',
                    'Choir and worship singers who want to decorate a line with care.',
                    'Anyone who has tried a fast run and heard it smear.',
                ],
                'need' => [
                    'A quiet spot where you can sing at a medium volume.',
                    'A few minutes a day: the lessons are short.',
                    'No reading music: you hear each run and see it drawn.',
                ],
                'safety' => [
                    'Runs need a light voice: medium volume, the middle of your voice, no pushing or squeezing.',
                    'The run happens in the voice, not the jaw.',
                    'At most two run lessons in a row, and about ten minutes of runs a day. Stop if anything tightens.',
                ],
                'faq' => [
                    ['How long does it take?', 'Lessons of five minutes or less. A lesson a day suits it, with no more than two run lessons in a row.'],
                    ['Will it make my runs fast?', 'It teaches clean runs, slow and well placed, which is how every fast run is learned. The lessons climb from 2 to 4 notes a second. Quicker runs are a check you make yourself, because the app doesn\'t score that speed yet.'],
                    ['Which songs does it use?', 'Its own runs on the major and minor pentatonic, then lines of public-domain spirituals: Swing Low, Wade in the Water and Steal Away. Each line is sung plain first; the runs on it are ours, and marked as ours.'],
                    ['Do I need a big voice?', 'No. Runs need a light voice at a medium volume. The course never teaches a faked rasp, which squeezes the throat.'],
                    ['Do I need to read music?', 'No. You hear each run from a guide and see your voice drawn as a line.'],
                    ['What does it cost?', 'Its first lesson is free, with no account needed. The rest is part of Plus; saving your progress takes a free account.'],
                ],
                'related' => ['pop-and-country', 'improvising-harmony', 'barbershop'],
                'close' => 'Lesson 1 takes about five minutes: five notes down the stairs on "Amen", slow and clean.',
                // The love letter (docs/courses/gospel-runs-love-letter.md): only its facts, each with its notes.
                'love' => [
                    // The hero's picture: the major pentatonic as five stairs, F and B left out.
                    'stairs' => [
                        'names' => ['C', 'D', 'E', 'F', 'G', 'A', 'B', 'C'],
                        'legend' => ['The five stairs: C, D, E, G and A, then C again', 'The gaps: F and B, the fourth and seventh', 'The run in the demo, down from C5 to C4'],
                        'note' => 'In 1872 Theodore Seward, writing down the Fisk Jubilee songs, found that "more than half the melodies" used a scale "with the fourth and seventh tones omitted": these five stairs.',
                    ],
                    'kicks' => [
                        'plain' => 'In plain words',
                        'blue' => 'The blue note',
                        'archive' => 'From the archive',
                        'climb' => 'The course',
                        'first' => 'Lesson 1',
                        'notes' => 'Margin notes',
                        'kit' => 'Before you begin',
                        'close' => 'Begin slow',
                    ],
                    // The featured demo (js/public/gospel-runs.js): the pack's "Slow, then fast".
                    'demo' => [
                        'live' => 'Live demo',
                        'tag' => 'No mic, just listen',
                        'title' => 'One run, three speeds',
                        'lead' => 'A synth voice sings one run down the five stairs, C5, A4, G4, E4, D4 and C4, at 2 notes a second, then 4, then 8. Each note glides into the next over 40 ms, the way a voice slides.',
                        'how' => 'Listen for how much of each note is left once the glide is done. At 8 a second each note lasts 125 ms, about as long as a 4-semitone slide at top speed, as measured in speech research. Slow and clean comes first.',
                        'play' => 'Slow, then faster',
                        'stop' => 'Stop',
                        'speeds' => ['2 a second', '4 a second', '8 a second'],
                        'key' => ['A note of the run', 'The note sounding'],
                        'ready' => 'Press play: the same six notes down the stairs, three times, quicker each time.',
                        'say' => ':rate notes a second: :note',
                        'after' => 'At 2 a second every note has time to land. The course\'s ladder climbs from 2 to 4 a second, every rung clean.',
                        'note' => 'A synth, not a singer. In the course, the app hears your own run, note by note.',
                    ],
                    'plain' => [
                        'title' => 'A run is a melisma, sung fast',
                        'lead' => 'A melisma is one syllable sung across several notes: in a cross-cultural song database\'s words, the "degree to which the same syllable of text is sung to two or more notes of melody". Writing down the Fisk songs in 1872, Theodore Seward noticed "one particular effect" that kept coming back: the one "on the last syllable of the word \'chariot\'" in Swing Low.',
                        'pent' => 'Why the five stairs sit so easily: one theory says we favour scales whose notes line up with the harmonics of a single voice. Testing 455,126 possible five-note scales against that rule, two neuroscientists found the minor pentatonic came out on top.',
                        'blur_title' => 'Why fast runs smear',
                        'blur' => 'The voice can\'t jump from one pitch to the next. It has to slide, and the slide takes time.',
                        'numbers' => [
                            ['124 ms', 'A fast slide, in speech', 'In a 2002 lab study, people rising 4 semitones as fast as they could took about 124 ms on average; falling took about the same. They were speakers, not trained singers.'],
                            ['120 ms', 'Each end of a sung note', 'A 2019 study of SATB quartets found "transient parts of approximately 120 ms duration at both the beginning and end of a note, where the pitch varies rapidly".'],
                            ['125 ms', 'A note, at 8 a second', 'Our arithmetic: at 8 notes a second each note lasts 125 ms, about as long as one of those slides. A careless fast run can spend the whole note sliding and never settle on a pitch. That is the smear.'],
                        ],
                        'slow_title' => 'Slow, and correct',
                        'slow' => 'In a 2013 study, people practised a piano finger pattern over several days, below their top speed. Their top speed "progressively increased", and the gain was still there two months later.',
                        'correct' => 'A study of 17 pianists found that practice time did not predict how well they played the next day. How many of their practice runs were correct did.',
                    ],
                    // The second demo: the same run at 8 a second, clean and then smeared, its pitch drawn.
                    'smear' => [
                        'kick' => 'Hear the smear',
                        'tag' => '8 notes a second',
                        'play' => 'Clean, then smeared',
                        'stop' => 'Stop',
                        'labels' => ['Clean', 'Smeared'],
                        'ready' => 'Press play: the run at 8 a second, sung clean, then smeared. The lines are its pitch.',
                        'say_clean' => 'Clean: each note glides in for 20 ms, then holds its pitch.',
                        'say_smear' => 'Smeared: each note spends all 125 ms gliding, and never sits on a pitch.',
                        'after' => 'In the clean one, every note is there to hear. That is what the course scores: each note landed.',
                        'key' => ['The pitch, drawn', 'Sounding now'],
                        'note' => 'A synth, not a singer. Both runs have the same notes at the same speed; only the glide changes.',
                    ],
                    // The third demo: a bend from the minor third's key to the major third's over a C drone.
                    'blue' => [
                        'title' => 'Between the keys, nearer the minor',
                        'lead' => 'Blue notes are the notes "between the cracks" of the usual pitches. A University of Rochester team tracked the pitch of isolated rock vocals and found a few notes sung "midway between the major and minor third", most of all where the music pulls both ways.',
                        'measured' => 'A 2019 study measured the notes in fifteen classic blues recordings. Its blue third clustered at 319.1 cents above the tonic: a little above the piano\'s minor third (300 cents) and far below its major third (400). It also confirmed a "neutral" third in between.',
                        'kick' => 'Bend the blue note',
                        'tag' => 'Over a C drone',
                        'play' => 'Bend up',
                        'stop' => 'Stop',
                        'slider' => 'Stop the bend at',
                        'cents' => ':n cents',
                        'hz' => ':n Hz',
                        'ready' => 'Press play: a drone on C3 and C4, and a voice bending up from E♭4.',
                        'say_bend' => 'Bending up from E♭4, 300 cents above C.',
                        'say_hold' => 'Held at :n cents over the drone. Move the slider to bend it.',
                        'after' => 'In the course, a bend arrives on the third and holds: the start is loose, the arrival is what matters.',
                        'marks' => [
                            [300, 'E♭4: the minor third, a piano key'],
                            [319, 'Where the blues study\'s thirds clustered'],
                            [350, 'The exact middle'],
                            [400, 'E4: the major third, a piano key'],
                        ],
                        'note' => 'A synth, not a singer. Neither 319 nor 350 cents is a piano key.',
                    ],
                    'archive' => [
                        'title' => 'Where the runs come from',
                        'more' => 'Four more, 1873 to 1948',
                        'rows' => [
                            ['1644', 'Westminster to the rural South', 'One line at a time', 'The Westminster Assembly, appointed by the English Parliament, recommended lining out, and Massachusetts took it up a few years later. In the Kentucky churches that still sing the old way, the leader "briefly chants a line alone, and then the group repeats the words but to a tune that is much longer and more elaborate", very slow, with no beat you can tap. African American congregations made it their own, particularly Baptists in the rural South, and it went on to influence music "from gospel to soul to jazz". It is also called "Dr. Watts" hymn singing, after the English hymn writer Isaac Watts (1674 to 1748).', ['titon', 'dargan', 'hymnary']],
                            ['1867', 'St. Helena Island, South Carolina', 'Slides and turns', 'Slave Songs of the United States was gathered "chiefly at Coffin\'s Point, St. Helena Island". Its editors warned that print could not hold the singing, with its "slides from one note to another, and turns and cadences not in articulated notes". Lucy McKim wrote of "the odd turns made in the throat". At a praise meeting, an elder was heard "\'deaconing\' a hymn-book hymn, which is sung two lines at a time": lining out again.', ['slavesongs']],
                            ['1873', 'London', 'Before the Queen', 'Fisk\'s treasurer, George L. White, had formed the Fisk Jubilee Singers and named them. In 1873 they sailed for Britain to raise money for their university. After a private concert at Willis\'s Rooms on 6 May, the Duke and Duchess of Argyll invited them to Argyll Lodge the next day, where Queen Victoria came to hear them. They sang "Steal away to Jesus", chanted the Lord\'s Prayer, and sang "Go down, Moses". Nearly £10,000 was raised for Jubilee Hall that season; the hall, Fisk\'s first permanent building, was dedicated on 1 January 1876.', ['emory', 'marsh', 'tna', 'tnenc']],
                            ['1932', 'Chicago', 'Precious Lord', 'Thomas A. Dorsey grew up near Villa Rica, Georgia, where he heard shape-note singing at Mt. Prospect Baptist Church, and moved to Chicago in 1919 in the Great Migration as a young blues pianist. His wife and newborn son died on 26 and 27 August 1932. Afterwards he wrote "Take My Hand, Precious Lord", which his Georgia marker calls "the world\'s most popular gospel-blues song". He was music director at Pilgrim Baptist Church in Chicago from 1932 until the late 1970s.', ['ghs', 'tulane']],
                            ['1938', 'New York', 'Gospel at Carnegie Hall', 'Rosetta Tharpe was born in Cotton Plant, Arkansas, in 1915, to an evangelist and singer of the Church of God in Christ, and toured the South with her mother before they reached Chicago. In 1938 she signed with Decca, "the first gospel performer to record for a major record label", and that December she sang in John Hammond\'s "From Spirituals to Swing" at Carnegie Hall. On guitar she "played individual tones, melodies, and riffs instead of just strumming chords".', ['eoa']],
                            ['1948', 'New Orleans to Chicago', 'A little higher', 'Mahalia Jackson was born in New Orleans on 26 October 1911 and grew up in a strict, religious household. At sixteen she moved to Chicago and began singing professionally, and in the early 1940s she worked with Thomas A. Dorsey. Her breakout came in 1948 with "Move on up a Little Higher". She sang at the 1963 March on Washington and died on 27 January 1972.', ['parishes']],
                        ],
                    ],
                    'facts_title' => 'Small things worth knowing',
                    'facts_more' => 'Five more',
                    'facts' => [
                        ['For a while, any new gospel-blues song, whoever wrote it, was called "a Dorsey", until Thomas A. Dorsey coined the name "gospel" himself, so his Georgia marker says.', 'Georgia Historical Society marker (1994)', ['ghs']],
                        ['Queen Victoria gave the Fisk Jubilee Singers a large portrait of the group by her court painter, Edmund Havell. It hangs in Jubilee Hall, the building their singing paid for.', 'The National Archives (UK)', ['tna']],
                        ['Ella Sheppard, the Jubilee Singers\' pianist and assistant trainer, and later Fisk\'s music teacher, was born enslaved in Nashville in 1851. Her father bought her freedom for $350.', 'Tennessee State University Library', ['tsu']],
                        ['"Take My Hand, Precious Lord" has been translated into 32 languages.', 'Georgia Historical Society marker (1994)', ['ghs']],
                        ['In early speech studies, the voice dropped in pitch faster than it climbed: a 4-semitone rise took about 79 ms to get through its middle part, a 4-semitone drop about 68 ms.', 'J. Acoust. Soc. Am. (2002)', ['xu']],
                        ['Singers tend to end a note with a small downward slide: in SATB quartets, "all singers tend to have a descending transient at the end of a note".', 'J. Acoust. Soc. Am. (2019)', ['dai']],
                        ['In early blues, the flat seventh is not one note but three: its measured pitches fell into "three separate clusters".', 'Empirical Musicology Review (2019)', ['cutting']],
                    ],
                    // The sources (docs/courses/gospel-runs-love-letter.md), numbered in this order.
                    'sources' => [
                        'jubilee' => ['Jubilee Songs, as sung by the Jubilee Singers of Fisk University (1872), preface', 'https://archive.org/details/jubileesongsassu00jubi'],
                        'xu' => ['Journal of the Acoustical Society of America (2002), on the maximum speed of pitch change', 'https://doi.org/10.1121/1.1445789'],
                        'jukebox' => ['PLoS ONE (2022), The Global Jukebox', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9629617/'],
                        'gill' => ['PLoS ONE (2009), a biological rationale for musical scales', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2779864/'],
                        'dai' => ['Journal of the Acoustical Society of America (2019), on intonation within tones in SATB quartets', 'https://doi.org/10.1121/1.5120483'],
                        'furuya' => ['BMC Neuroscience (2013), on practice below top speed', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4228459/'],
                        'duke' => ['Journal of Research in Music Education (2009), It\'s Not How Much; It\'s How', 'https://doi.org/10.1177/0022429408328851'],
                        'rochester' => ['University of Rochester (2017), Unlocking the secrets of blue notes', 'https://www.rochester.edu/newscenter/unlocking-the-secrets-of-blue-notes-230482/'],
                        'temperley' => ['Music Theory Online 23.1 (2017), on mediant mixture and blue notes in rock', 'https://mtosmt.org/issues/mto.17.23.1/mto.17.23.1.temperley.html'],
                        'cutting' => ['Empirical Musicology Review (2019), on blue notes and the blues scale', 'https://doi.org/10.18061/emr.v13i1-2.6316'],
                        'titon' => ['Smithsonian Festival of American Folklife program book (1997), Old Regular Baptists of Southeastern Kentucky', 'https://folklife-media.si.edu/docs/festival/program-book-articles/FESTBK1997_25.pdf'],
                        'dargan' => ['University of California Press (2006), Lining Out the Word: Dr. Watts Hymn Singing in the Music of Black Americans', 'https://www.ucpress.edu/books/lining-out-the-word/hardcover'],
                        'hymnary' => ['Hymnary.org, Isaac Watts', 'https://hymnary.org/person/Watts_Isaac'],
                        'slavesongs' => ['Allen, Ware and Garrison, Slave Songs of the United States (1867)', 'https://archive.org/details/slavesongsofunit00alle'],
                        'emory' => ['Jubilee Songs (1872), Emory copy, catalogue record', 'https://archive.org/details/29208201.4853.emory.edu'],
                        'marsh' => ['Marsh, The Story of the Jubilee Singers (1876)', 'https://archive.org/details/storyofjubileesi00mars_3'],
                        'tna' => ['The National Archives (UK), Photograph of the Jubilee Singers', 'https://www.nationalarchives.gov.uk/explore-the-collection/stories/photograph-of-the-jubilee-singers/'],
                        'tnenc' => ['Tennessee Encyclopedia, Jubilee Singers of Fisk University', 'https://tennesseeencyclopedia.net/entries/jubilee-singers-of-fisk-university/'],
                        'ghs' => ['Georgia Historical Society, marker: Thomas A. Dorsey, Father of Gospel (1994)', 'https://www.georgiahistory.com/ghmi_marker_updated/thomas-a-dorsey/'],
                        'tulane' => ['Tulane University, Music Rising: Thomas A. Dorsey', 'https://musicrising.tulane.edu/?p=1799'],
                        'eoa' => ['Encyclopedia of Arkansas, "Sister Rosetta" Tharpe', 'https://encyclopediaofarkansas.net/entries/sister-rosetta-tharpe-1781/'],
                        'parishes' => ['64 Parishes (Louisiana Endowment for the Humanities), Mahalia Jackson', 'https://64parishes.org/entry/mahalia-jackson'],
                        'tsu' => ['Tennessee State University Library, Ella Sheppard (Moore)', 'https://ww2.tnstate.edu/library/digital/sheppard.htm'],
                    ],
