                        'style' => 'How the notes join',
                        'legato' => 'Smeared',
                        'crisp' => 'Crisp',
                        'stave' => 'The first two lines on a stave, each syllable under its note.',
                        // The words under the notes: Gilbert's, one syllable a note.
                        'lyric' => ['I', 'am', 'the', 've-', 'ry', 'mod-', 'el', 'of', 'a', 'mo-', 'dern', 'Ma-', 'jor-', 'Gi-', 'ne-', 'ral;', 'I\'ve', 'in-', 'for-', 'ma-', 'tion', 've-', 'ge-', 'ta-', 'ble,', 'an-', 'i-', 'mal,', 'and', 'mi-', 'ne-', 'ral;', 'I'],
                        'ready' => 'Play it, then try it quicker, and crisp.',
                        'playing_legato' => 'Smeared: each note runs into the next, and the syllables blur.',
                        'playing_crisp' => 'Crisp: short notes with small gaps, so each syllable lands.',
                        'after' => 'Now the other way, or a little quicker.',
                        'note' => 'Read from the Chappell vocal score, No. 13, page 61. It\'s printed in the treble clef, so a baritone sings it an octave lower, and so does this demo: the small 8 under the clef says so. The fast end is our guess. A synth voice can\'t say words, so they light up under the notes. No mic: the demo only plays.',
                    ],
                    // The story, from the research pack (docs/courses/musical-theatre-love-letter.md): [when, title, text, notes].
                    'story' => [
                        ['1728', 'An opera on borrowed tunes', 'John Gay\'s The Beggar\'s Opera opened on 29 January 1728 at John Rich\'s theatre in Lincoln\'s Inn Fields, after Colley Cibber had refused it for Drury Lane. Its songs were new words set to tunes everyone already knew, like "Lillibullero" and "Green Sleeves". It ran 62 nights that season, 32 of them in a row; a joke of the day said it "made Gay rich and Rich gay". Lavinia Fenton, the Polly, "till then obscure, became all at once the favourite of the town".', ['melville', 'gay']],
                        ['1877', 'Sing it out as loud as you can', 'Arthur Sullivan wanted the entertainer George Grossmith for a part in his new piece with W. S. Gilbert. Grossmith\'s father doubted he had voice enough, so Sullivan struck the D on the fourth line of the treble staff: "Sing it out as loud as you can." Then: "Beautiful!" Grossmith told Gilbert a magician surely needed "a fine man with a fine voice". Gilbert: "No; that is just what we don\'t want."', ['grossmith']],
                        ['1879', 'A premiere to beat the pirates', 'With no copyright protection, H.M.S. Pinafore "arrived in Boston as a pirated production in November 1878 and soon took the nation by storm". So in December 1879 Gilbert, Sullivan and Richard D\'Oyly Carte brought their own Pinafore to America, and The Pirates of Penzance opened at the Fifth Avenue Theatre, New York, on 31 December 1879, Sullivan conducting. To protect the British copyright, it was staged the day before at the Royal Bijou Theatre, Paignton.', ['lytton', 'vam', 'programme', 'gmu']],
                        ['1881', 'Faces in electric light', 'The Savoy Theatre opened on 10 October 1881 with Patience. Carte said no attempt had yet been made "to light a public building entirely by electricity". The auditorium was lit that night; the stage followed on 28 December, with Swan\'s incandescent lamps and no gas at all, and The Times found the costumes "as true and distinct as by daylight". To show the lamps were safe, Carte wrapped one in muslin and the glass was broken: the light went out "without even singeing the muslin".', ['standard', 'times']],
                        ['1885', 'Turn round so we can hear you', 'In early rehearsals of The Mikado, Gilbert had the chorus bow to the Mikado with their backs to the audience. Sullivan said "the voices could not be well heard from the front", and Gilbert changed it at once to a semicircle. He insisted his words be "delivered, even to an inflection of the voice, as he dictates". The opera opened at the Savoy on 14 March 1885.', ['grossmith', 'mikado']],
                        ['1899', 'Rhythm before melody', '"The first thing I have to decide upon is the rhythm," Sullivan told his biographer, "and I arrange the rhythm before I come to the question of melody." He showed it with Phoebe\'s song "Were I thy bride" from The Yeomen of the Guard (1888), trying rhythms out in dummy bars; when he couldn\'t get the accent right any other way, he would "mark out the metre in dots and dashes".', ['lawrence', 'plays']],
                    ],
                    // The science, in plain words: [title, text, notes]; the last card is the course's own line.
                    'science' => [
                        ['Belt and legit, measured', 'Music theatre singers name their sounds: "legit", and belt. When six of them sang the same notes both ways, from F sharp 4 to D5 (about 370 to 600 Hz), belt raised the vocal tract\'s first resonance onto the note\'s second harmonic, twice its frequency, up to C5: on A4, 440 Hz, that\'s 880 Hz. Belt also kept the vocal folds closed longer in each cycle, was louder, and had more energy above 1 kHz. Men in music theatre, against opera singers at the same breath pressure, showed the same pattern.', ['jasa12', 'jv08']],
                        ['Belt, honestly', 'In an early lab study of one singer trained in both styles, belting used "very high subglottal pressures and sound levels". The authors note belting "is frequently associated with disturbances of voice function": an association, not a proof of harm, and the studies are small, one to ten singers. A computer model suggests belt\'s ring comes better from the vowel than from squeezing, the mouth shaped like a "megaphone (trumpet-like)". Mix measured between legit and belt, and each singer made it differently.', ['jv93', 'jasa09', 'jasa12']],
                        ['Heard without a microphone', 'An orchestra is loudest around 500 Hz and weaker higher up. Trained opera voices add a peak near 3 kHz, the "singer\'s formant", mainly from bunching the vocal tract\'s third, fourth and fifth resonances. It fills the band\'s gap, so the voice carries. Sopranos aren\'t thought to have the classic peak, yet those with more energy between 2 and 4 kHz tended to be the higher-level performers. And singers send that high band forward more narrowly than their low notes.', ['ncvs', 'jv01', 'jasa04s', 'jv11']],
                        ['Speech and song', 'Expert listeners mostly agreed which singers were classical and which music theatre, even from scales alone. The classical singers\' strongest band was the note itself; the music theatre singers peaked near 1 kHz and again at 4 to 5 kHz, the region of the "speaker\'s formant". In a model of one singer, opera and belt both passed energy from the folds to the air efficiently, and "should thus be capable of" carrying over an orchestra, by different vowel strategies.', ['jv17', 'frontiers']],
                        ['Vowels bend up high', 'Low down, sopranos\' vowels sit where speech vowels do. When the note climbs above a vowel\'s first resonance, they raise that resonance to match it, and vowels "move, converge, and overlap". Listeners named sung vowels less well as the pitch rose (tested from F3 to B5, 175 to 988 Hz). So the words that matter most are easiest to catch lower down.', ['jasa04', 'jv14']],
                    ],
                    'science_course' => ['What the course does with it', 'Every line is set from your comfortable note, so the words sit where they\'re easy to catch. It builds a bright line from speech, at a medium volume, and holds legit\'s tall vowel steady. It never asks for belt, and never asks you to be loud: the app can\'t judge loudness, and your voice shouldn\'t be pushed for it.'],
                    // Backstage (the pack's surprising facts): [text, notes].
                    'margin' => [
                        ['Sullivan said "five out of six methods were commonplace" for "Were I thy bride". The facsimile printed with his words shows eight numbered tries: No. 6 is marked "no good", and No. 8 "as it stands in the Opera now".', ['lawrence']],
                        ['Gilbert planned every staging on "exact models of the Savoy Theatre", with the cast as "little bricks of various colours". The model ship for a Pinafore revival cost £60.', ['grossmith']],
                        ['The Savoy\'s first electric stage lights were dimmed with "open spiral coils of iron wire". Before that, electric light had "no medium between full light and total darkness".', ['times']],
                        ['The highwaymen\'s air "Let us take the Road" in The Beggar\'s Opera is sung to a march from Handel\'s opera Rinaldo, "with Drums and Trumpets".', ['gay']],
                        ['Asked what to do with his hands, Henry Lytton got this from Gilbert: "Cut them off at the wrists, Lytton," and "forget you\'ve got any hands!" Gilbert also kept speakers well downstage, or "you also lose the power of clear and effective speech".', ['lytton']],
                        ['Henry Irving told the young Lytton to imagine a friend "who could not afford the stalls" at the back of the gallery. "Let him hear every line you have to say."', ['lytton']],
                    ],
                    // The company: [name, years, what they did, notes].
                    'company' => [
                        ['John Gay', '1685 to 1732', 'Poet; The Beggar\'s Opera (1728), the ballad opera on tunes everyone knew.', ['melville', 'loc-gay']],
                        ['Lavinia Fenton', '1708 to 1760', 'The first Polly Peachum; she played every night of the first run, then left the stage, and in 1751 married the Duke of Bolton.', ['melville', 'loc-fenton']],
                        ['W. S. Gilbert', '1836 to 1911', 'Librettist and stage director, who wanted every word "delivered, even to an inflection of the voice, as he dictates".', ['grossmith', 'loc-gilbert']],
                        ['Arthur Sullivan', '1842 to 1900', 'Composer: rhythm first, then melody. He conducted the New York premiere of The Pirates of Penzance.', ['lawrence', 'lytton', 'loc-sullivan']],
                        ['Richard D\'Oyly Carte', '1844 to 1901', 'Producer, and proprietor of the Savoy, which he lit by electricity.', ['standard', 'times', 'loc-carte']],
                        ['George Grossmith', '1847 to 1912', 'The first John Wellington Wells, Bunthorne and Ko-Ko; Gilbert didn\'t want "a fine man with a fine voice" for him.', ['grossmith', 'standard', 'mikado', 'loc-grossmith']],
                        ['Henry Lytton', '1865 to 1936', 'Rose from the Savoy chorus to the leading comic parts, and wrote down Gilbert\'s rules for clear speech.', ['lytton', 'loc-lytton']],
                        ['Sir Henry Irving', '1838 to 1905', 'Actor: "Let him hear every line."', ['lytton', 'loc-irving']],
                        ['George M. Cohan', '1878 to 1942', 'From the family act "The Four Cohans" to Little Johnny Jones (1904), with "Give My Regards to Broadway".', ['cohan', 'loc-cohan']],
                    ],
                    // On a phone, the rest of a long list folds under these (open on a wide screen).
                    'more' => ['story' => 'More of the story', 'science' => 'More of the science', 'margin' => 'More from backstage', 'company' => 'The whole company'],
                    // The sources (docs/courses/musical-theatre-love-letter.md), numbered in this order.
                    'sources' => [
                        'score' => ['Sullivan, The Pirates of Penzance, Chappell vocal score, No. 13, p. 61', 'https://archive.org/details/vocalscoreofpira00sull'],
                        'melville' => ['Melville, Life and Letters of John Gay (1921)', 'https://www.gutenberg.org/ebooks/13790'],
                        'gay' => ['Gay, The Beggar\'s Opera, text and music of the 1765 edition (1921)', 'https://www.gutenberg.org/ebooks/25063'],
                        'grossmith' => ['Grossmith, A Society Clown (1888)', 'https://www.gutenberg.org/ebooks/53225'],
                        'lytton' => ['Lytton, The Secrets of a Savoyard (1922)', 'https://www.gutenberg.org/ebooks/39392'],
                        'vam' => ['Victoria and Albert Museum, H.M.S. Pinafore', 'https://collections.vam.ac.uk/item/O1331656'],
                        'programme' => ['Victoria and Albert Museum, silk programme for the New York premiere', 'https://collections.vam.ac.uk/item/O1370508/the-pirates-of-penzance-silk-programme-seer-a-s/'],
                        'gmu' => ['George Mason University Libraries, Gilbert and Sullivan Productions in America', 'https://gilbertandsullivan2017.gmu.edu/exhibits/show/gsamerica'],
                        'standard' => ['The Standard, 11 October 1881', 'https://gsarchive.net/carte/savoy/std811011.html'],
